<template><div class="page"><header class="page-head"><div><h1>Analysis History</h1><p>Open a previous PRD analysis without running it again.</p></div><RouterLink class="primary" to="/">+ New Analysis</RouterLink></header><section class="card history"><article v-for="x in items" :key="x.id" class="history-row"><div class="history-icon">✦</div><div class="history-main"><b>{{x.name}}</b><span>{{x.perspectives.length}} perspectives · {{x.scenarios.length}} scenarios · {{x.createdAt}}</span></div><span class="status">Completed</span><button class="ghost-btn" @click="$router.push(`/analysis/${x.id}`)">Open</button></article></section></div></template>
